import React, { useState, useEffect } from "react";
import { getMatches, getTeamComparison } from "../api";

function ComparePage() {
  const [allTeams, setAllTeams] = useState([]);
  const [team1, setTeam1] = useState("");
  const [team2, setTeam2] = useState("");
  const [comparisonData, setComparisonData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // Подгружаем список команд для подсказок
  useEffect(() => {
    const fetchTeams = async () => {
      const data = await getMatches(null);
      const teamSet = new Set();
      data.forEach((m) => {
        if (m.homeTeam?.name) teamSet.add(m.homeTeam.name);
        if (m.homeTeam?.name_ru) teamSet.add(m.homeTeam.name_ru);
      });
      setAllTeams(Array.from(teamSet).sort());
    };
    fetchTeams();
  }, []);

  const handleCompare = async () => {
    if (!team1 || !team2) {
      setError("Выберите обе команды для сравнения");
      return;
    }
    setLoading(true);
    setError("");
    const data = await getTeamComparison(team1, team2);
    if (data) {
      setComparisonData(data);
    } else {
      setError("Обе или одна из команд не найдены в базе");
    }
    setLoading(false);
  };

  const ResultCircle = ({ res }) => {
    const colors = { W: "bg-green-500", D: "bg-yellow-500", L: "bg-red-600" };
    return (
      <span
        className={`${colors[res]} w-5 h-5 rounded-full flex items-center justify-center text-[9px] font-black text-white shadow-lg`}
      >
        {res}
      </span>
    );
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-8 text-white font-sans">
      <h1 className="text-2xl md:text-3xl font-black text-center uppercase tracking-tighter mb-8">
        H2H <span className="text-red-600">Сравнение</span>
      </h1>

      {/* ПАНЕЛЬ ВЫБОРА КОМАНД */}
      <div className="bg-gray-900 p-6 md:p-8 rounded-[32px] border border-gray-800 shadow-2xl mb-10 flex flex-col md:flex-row items-center justify-between gap-4">
        <div className="w-full md:w-2/5">
          <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest ml-4">
            Команда 1
          </label>
          <input
            type="text"
            list="teams-list"
            value={team1}
            onChange={(e) => setTeam1(e.target.value)}
            placeholder="Введите название..."
            className="w-full mt-2 bg-gray-950 border border-gray-800 rounded-xl py-3 px-5 text-sm text-white focus:outline-none focus:border-red-600 transition-all"
          />
        </div>

        <button
          onClick={handleCompare}
          className="w-full md:w-auto px-8 py-3 bg-red-600 hover:bg-red-700 text-white font-black uppercase tracking-widest text-xs rounded-xl transition-all shadow-lg shadow-red-600/20 mt-4 md:mt-0"
        >
          Сравнить
        </button>

        <div className="w-full md:w-2/5">
          <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest ml-4">
            Команда 2
          </label>
          <input
            type="text"
            list="teams-list"
            value={team2}
            onChange={(e) => setTeam2(e.target.value)}
            placeholder="Введите название..."
            className="w-full mt-2 bg-gray-950 border border-gray-800 rounded-xl py-3 px-5 text-sm text-white focus:outline-none focus:border-red-600 transition-all"
          />
        </div>

        {/* Нативный Datalist для подсказок */}
        <datalist id="teams-list">
          {allTeams.map((t, idx) => (
            <option key={idx} value={t} />
          ))}
        </datalist>
      </div>

      {error && (
        <div className="text-center text-red-500 font-bold mb-8 bg-red-500/10 py-4 rounded-xl">
          {error}
        </div>
      )}
      {loading && (
        <div className="text-center text-gray-500 font-black tracking-widest uppercase animate-pulse py-20">
          Сбор аналитики...
        </div>
      )}

      {/* РЕЗУЛЬТАТЫ СРАВНЕНИЯ */}
      {comparisonData && !loading && (
        <div className="bg-gray-900 rounded-[32px] p-8 md:p-12 border border-gray-800 shadow-xl animate-in fade-in zoom-in duration-500">
          {/* ШАПКА */}
          <div className="flex justify-between items-center mb-12">
            <div className="flex flex-col items-center w-1/3">
              <img
                src={comparisonData.team1.logo_url}
                className="h-20 w-20 md:h-28 md:w-28 object-contain mb-4"
                alt=""
              />
              <h2 className="text-xl md:text-2xl font-black uppercase text-center">
                {comparisonData.team1.name}
              </h2>
              <span className="mt-2 text-[10px] text-yellow-500 font-mono bg-gray-800 px-3 py-1 rounded-full">
                ELO: {Math.round(comparisonData.team1.elo)}
              </span>
              <div className="flex gap-1 mt-3">
                {comparisonData.team1.stats.form.map((r, i) => (
                  <ResultCircle key={i} res={r} />
                ))}
              </div>
            </div>
            <div className="text-3xl md:text-5xl font-black text-gray-800 italic">
              VS
            </div>
            <div className="flex flex-col items-center w-1/3">
              <img
                src={comparisonData.team2.logo_url}
                className="h-20 w-20 md:h-28 md:w-28 object-contain mb-4"
                alt=""
              />
              <h2 className="text-xl md:text-2xl font-black uppercase text-center">
                {comparisonData.team2.name}
              </h2>
              <span className="mt-2 text-[10px] text-yellow-500 font-mono bg-gray-800 px-3 py-1 rounded-full">
                ELO: {Math.round(comparisonData.team2.elo)}
              </span>
              <div className="flex gap-1 mt-3">
                {comparisonData.team2.stats.form.map((r, i) => (
                  <ResultCircle key={i} res={r} />
                ))}
              </div>
            </div>
          </div>

          {/* ГРАФИКИ */}
          <div className="space-y-8">
            <div className="text-center mb-6">
              <span className="bg-white/10 text-white text-[10px] font-black uppercase tracking-widest px-4 py-1.5 rounded-full">
                Атака (Последние 5 матчей)
              </span>
            </div>
            <StatBar
              label="Забитые голы"
              h={comparisonData.team1.stats.gf}
              a={comparisonData.team2.stats.gf}
              color="bg-green-500"
            />
            <StatBar
              label="xG (Ожидаемые голы)"
              h={comparisonData.team1.stats.xg_for}
              a={comparisonData.team2.stats.xg_for}
              color="bg-green-500"
            />
            <StatBar
              label="Глубокие атаки"
              h={comparisonData.team1.stats.deep}
              a={comparisonData.team2.stats.deep}
              color="bg-green-500"
            />

            <div className="text-center mb-6 mt-12">
              <span className="bg-white/10 text-white text-[10px] font-black uppercase tracking-widest px-4 py-1.5 rounded-full">
                Оборона (Последние 5 матчей)
              </span>
            </div>
            <StatBar
              label="Пропущенные голы"
              h={comparisonData.team1.stats.ga}
              a={comparisonData.team2.stats.ga}
              reverse
              color="bg-red-600"
            />
            <StatBar
              label="Допущенный xG"
              h={comparisonData.team1.stats.xg_against}
              a={comparisonData.team2.stats.xg_against}
              reverse
              color="bg-red-600"
            />
            <StatBar
              label="Прессинг (PPDA)"
              h={comparisonData.team1.stats.ppda}
              a={comparisonData.team2.stats.ppda}
              reverse
              color="bg-red-600"
            />
          </div>
        </div>
      )}
    </div>
  );
}

const StatBar = ({ label, h, a, reverse, color }) => {
  const isHomeBetter = reverse ? h < a : h > a;
  const total = h + a || 1;
  return (
    <div className="relative group">
      <div className="flex justify-between items-end mb-2">
        <span className={`text-xl md:text-2xl font-black text-white`}>
          {h.toFixed(2)}
        </span>
        <span className="text-[9px] md:text-[11px] font-black text-white uppercase tracking-widest mb-1 text-center">
          {label}
        </span>
        <span className={`text-xl md:text-2xl font-black text-white`}>
          {a.toFixed(2)}
        </span>
      </div>
      <div className="h-2.5 w-full bg-gray-800 rounded-full flex overflow-hidden p-0.5 border border-gray-700">
        <div
          className={`h-full rounded-full transition-all duration-1000 ${isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${(h / total) * 100}%` }}
        ></div>
        <div
          className={`h-full rounded-full transition-all duration-1000 ${!isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${(a / total) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

export default ComparePage;
